using Xunit;

public class RequirementStorageTest
{
    [Fact]
    public void Requirement_Storage_Shall_Store_Requirements_In_Permanent_And_Secure_Manner()
    {
        // Arrange
        var requirements = new List<Requirement> { new Requirement { Id = "REQ011", Description = "Store requirements in a permanent and secure manner" } };

        // Act
        RequirementStorage.StoreRequirements(requirements);

        // Assert
        Assert.True(RequirementStorage.RetrieveRequirements().Any(r => r.Id == "REQ011"));
    }

    [Fact]
    public void Requirement_Storage_Shall_Handle_Change_Management_Of_Requirements()
    {
        // Arrange
        var requirements = new List<Requirement> { new Requirement { Id = "REQ012", Description = "Handle change management of the requirements" } };

        // Act
        RequirementStorage.StoreRequirements(requirements);

        // Assert
        Assert.True(RequirementStorage.RetrieveRequirements().Any(r => r.Id == "REQ012"));
    }

    [Fact]
    public void Requirement_Storage_Shall_Associate_Requirements_Changes_To_Existing_Developer_Identification()
    {
        // Arrange
        var requirements = new List<Requirement> { new Requirement { Id = "REQ013", Description = "Associate requirements changes to existing developer identification" } };

        // Act
        RequirementStorage.StoreRequirements(requirements);

        // Assert
        Assert.True(RequirementStorage.RetrieveRequirements().Any(r => r.Id == "REQ013"));
    }

    [Fact]
    public void Requirement_Storage_Shall_Be_Scalable_To_Support_Thousands_Of_Requirements()
    {
        // Arrange
        var requirements = new List<Requirement>();
        for (int i = 0; i < 10000; i++)
        {
            requirements.Add(new Requirement { Id = $"REQ{i}", Description = $"Requirement {i}" });
        }

        // Act
        RequirementStorage.StoreRequirements(requirements);

        // Assert
        Assert.Equal(10000, RequirementStorage.RetrieveRequirements().Count());
    }

